## 캐시 무효화와 정합성

### 캐시 스탬피드(Stampede) 방지

인기 상품의 캐시가 만료되면, 수백 개 요청이 동시에 DB를 조회하는 **thundering herd** 현상 발생.

```kotlin
@Service
class StampedePreventionService(
    private val redisTemplate: RedisTemplate<String, String>,
    private val redissonClient: RedissonClient,
    private val productRepository: ProductRepository,
    private val objectMapper: ObjectMapper
) {

    // 방법 1: 분산 뮤텍스 (가장 확실)
    fun findByIdWithMutex(id: Long): Product? {
        val cacheKey = "product:$id"
        val lockKey = "lock:product:$id"

        // 캐시 조회
        redisTemplate.opsForValue().get(cacheKey)?.let {
            return objectMapper.readValue(it, Product::class.java)
        }

        // 분산 락 획득 시도
        val lock = redissonClient.getLock(lockKey)
        return try {
            if (lock.tryLock(3, 10, TimeUnit.SECONDS)) {
                // 더블 체크: 락 획득 사이에 다른 스레드가 채웠을 수 있음
                redisTemplate.opsForValue().get(cacheKey)?.let {
                    return objectMapper.readValue(it, Product::class.java)
                }

                val product = productRepository.findById(id).orElse(null)
                product?.let {
                    redisTemplate.opsForValue().set(
                        cacheKey, objectMapper.writeValueAsString(it),
                        ttlWithJitter(Duration.ofMinutes(30))
                    )
                }
                product
            } else {
                // 락 획득 실패 → 잠시 대기 후 캐시 재조회
                Thread.sleep(100)
                redisTemplate.opsForValue().get(cacheKey)?.let {
                    objectMapper.readValue(it, Product::class.java)
                }
            }
        } finally {
            if (lock.isHeldByCurrentThread) lock.unlock()
        }
    }

    // 방법 2: 확률적 조기 만료 (Probabilistic Early Expiration)
    fun findByIdWithProbabilisticExpiry(id: Long): Product? {
        val cacheKey = "product:$id"
        val metaKey = "meta:product:$id"

        val cached = redisTemplate.opsForValue().get(cacheKey) ?: return loadAndCache(id)
        val ttl = redisTemplate.getExpire(cacheKey, TimeUnit.SECONDS)

        // TTL이 임계값 이하일 때 확률적으로 갱신
        val threshold = 60L  // 60초 이하면 갱신 고려
        if (ttl < threshold && Random.nextDouble() < (1.0 - ttl.toDouble() / threshold)) {
            // 비동기로 갱신 (현재 요청은 기존 캐시 반환)
            CompletableFuture.runAsync { loadAndCache(id) }
        }

        return objectMapper.readValue(cached, Product::class.java)
    }

    private fun loadAndCache(id: Long): Product? {
        val product = productRepository.findById(id).orElse(null)
        product?.let {
            redisTemplate.opsForValue().set(
                "product:$id", objectMapper.writeValueAsString(it),
                ttlWithJitter(Duration.ofMinutes(30))
            )
        }
        return product
    }
}
```

### 이벤트 기반 캐시 무효화

```kotlin
// 도메인 이벤트 발행
@Service
class ProductService(
    private val productRepository: ProductRepository,
    private val applicationEventPublisher: ApplicationEventPublisher
) {
    @Transactional
    fun updatePrice(id: Long, newPrice: BigDecimal) {
        val product = productRepository.findById(id).orElseThrow()
        product.price = newPrice
        productRepository.save(product)

        // 이벤트 발행 → 캐시 리스너가 무효화 처리
        applicationEventPublisher.publishEvent(
            ProductUpdatedEvent(id, "price_changed")
        )
    }
}

// 이벤트 리스너에서 캐시 무효화
@Component
class CacheInvalidationListener(
    private val cacheManager: CacheManager
) {
    @EventListener
    fun handleProductUpdate(event: ProductUpdatedEvent) {
        cacheManager.getCache("products")?.evict(event.productId)
        cacheManager.getCache("productList")?.clear()
    }
}
```

### 캐시 웜업 전략

```kotlin
@Component
class CacheWarmupRunner(
    private val productService: ProductService,
    private val categoryService: CategoryService
) : ApplicationRunner {

    private val logger = LoggerFactory.getLogger(javaClass)

    override fun run(args: ApplicationArguments) {
        logger.info("캐시 웜업 시작...")

        // 인기 상품 Top 100 사전 로딩
        val topProducts = productService.findTopSellingProducts(100)
        topProducts.forEach { productService.findById(it.id) }

        // 카테고리 목록 사전 로딩
        categoryService.findAll()

        logger.info("캐시 웜업 완료: ${topProducts.size}개 상품 로딩")
    }
}
```

