## Spring Cache Abstraction

### 기본 어노테이션

```kotlin
@Service
class ProductService(
    private val productRepository: ProductRepository
) {

    // 캐시 조회 → 없으면 메서드 실행 → 결과 캐시
    @Cacheable(
        cacheNames = ["products"],
        key = "#id",
        unless = "#result == null"  // null은 캐시하지 않음
    )
    fun findById(id: Long): Product? {
        return productRepository.findById(id).orElse(null)
    }

    // 캐시 갱신 (메서드 항상 실행)
    @CachePut(cacheNames = ["products"], key = "#product.id")
    fun update(product: Product): Product {
        return productRepository.save(product)
    }

    // 캐시 삭제
    @CacheEvict(cacheNames = ["products"], key = "#id")
    fun delete(id: Long) {
        productRepository.deleteById(id)
    }

    // 복합 캐시 연산
    @Caching(
        evict = [
            CacheEvict(cacheNames = ["products"], key = "#product.id"),
            CacheEvict(cacheNames = ["productList"], allEntries = true)
        ],
        put = [
            CachePut(cacheNames = ["products"], key = "#product.id")
        ]
    )
    fun updateWithListInvalidation(product: Product): Product {
        return productRepository.save(product)
    }
}
```

> [!warning] 프록시 제약
> `@Cacheable`은 **AOP 프록시 기반**으로 동작한다. 같은 클래스 내부에서 호출하면 프록시를 거치지 않아 캐시가 작동하지 않는다.
>
> ```kotlin
> // ❌ 내부 호출 → 캐시 미적용
> fun process(id: Long) {
>     val product = findById(id)  // this.findById() → 프록시 우회
> }
>
> // ✅ 해결 1: 별도 클래스로 분리
> // ✅ 해결 2: self-injection
> @Lazy @Autowired lateinit var self: ProductService
> fun process(id: Long) {
>     val product = self.findById(id)  // 프록시 경유
> }
> ```

### CacheManager 커스터마이징

```kotlin
@Configuration
@EnableCaching
class CacheConfig {

    @Bean
    fun cacheManager(
        caffeineCacheManager: CaffeineCacheManager,
        redisCacheManager: RedisCacheManager
    ): CacheManager {
        // L1(Caffeine) + L2(Redis) 순서대로 조회
        return CompositeCacheManager(caffeineCacheManager, redisCacheManager).apply {
            isCompositeSorted = true
        }
    }

    @Bean
    fun caffeineCacheManager(): CaffeineCacheManager {
        return CaffeineCacheManager().apply {
            setCaffeine(
                Caffeine.newBuilder()
                    .maximumSize(1_000)
                    .expireAfterWrite(Duration.ofMinutes(5))
                    .recordStats()
            )
        }
    }

    @Bean
    fun redisCacheManager(connectionFactory: RedisConnectionFactory): RedisCacheManager {
        val config = RedisCacheConfiguration.defaultCacheConfig()
            .entryTtl(Duration.ofMinutes(30))
            .serializeValuesWith(
                RedisSerializationContext.SerializationPair
                    .fromSerializer(GenericJackson2JsonRedisSerializer())
            )
            .disableCachingNullValues()

        return RedisCacheManager.builder(connectionFactory)
            .cacheDefaults(config)
            .withCacheConfiguration("products",
                config.entryTtl(Duration.ofMinutes(30)))
            .withCacheConfiguration("stock",
                config.entryTtl(Duration.ofSeconds(30)))
            .build()
    }
}
```

