## 스키마 버전 관리

```kotlin
// 스키마 버전 필드로 점진적 마이그레이션
@Document(collection = "products")
data class Product(
    @Id val id: String? = null,
    val name: String,
    val price: BigDecimal,
    val schemaVersion: Int = 2,  // 현재 스키마 버전

    // v2에서 추가된 필드
    val specifications: Map<String, String>? = null
)

// 조회 시 구버전 문서 자동 마이그레이션
@Component
class ProductMigrator(private val mongoTemplate: MongoTemplate) {

    fun migrateIfNeeded(product: Product): Product {
        if (product.schemaVersion < 2) {
            val migrated = product.copy(
                schemaVersion = 2,
                specifications = product.specs ?: emptyMap()
            )
            mongoTemplate.save(migrated)
            return migrated
        }
        return product
    }
}
```

