## Spring Data MongoDB

### MongoTemplate vs MongoRepository

| 기준 | MongoRepository | MongoTemplate |
|------|----------------|---------------|
| **스타일** | Spring Data 인터페이스 | 명령형 API |
| **쿼리 방식** | 메서드명 파생, @Query | Criteria/Aggregation API |
| **유연성** | 제한적 | 매우 유연 |
| **적합** | 단순 CRUD | 복잡한 쿼리, 집계 |

### 기본 설정과 사용

```kotlin
// 문서 클래스
@Document(collection = "products")
data class Product(
    @Id val id: String? = null,
    val name: String,
    val price: BigDecimal,
    @Indexed val categoryId: String,
    val specs: Map<String, String> = emptyMap(),
    val tags: List<String> = emptyList(),

    // 임베디드 문서
    val reviewSummary: ReviewSummary = ReviewSummary(),

    @CreatedDate val createdAt: LocalDateTime? = null,
    @LastModifiedDate val updatedAt: LocalDateTime? = null
)

data class ReviewSummary(
    val averageRating: Double = 0.0,
    val totalCount: Int = 0
)

// Repository 인터페이스
interface ProductMongoRepository : MongoRepository<Product, String> {
    fun findByCategoryId(categoryId: String): List<Product>
    fun findByPriceGreaterThan(price: BigDecimal): List<Product>
    fun findByTagsContaining(tag: String): List<Product>

    @Query("{ 'name': { '\$regex': ?0, '\$options': 'i' } }")
    fun searchByName(keyword: String): List<Product>
}
```

### MongoTemplate로 복잡한 쿼리

```kotlin
@Repository
class ProductMongoQueryRepository(
    private val mongoTemplate: MongoTemplate
) {
    // 동적 검색
    fun search(condition: ProductSearchCondition): List<Product> {
        val query = Query()

        condition.categoryId?.let {
            query.addCriteria(Criteria.where("categoryId").`is`(it))
        }
        condition.minPrice?.let {
            query.addCriteria(Criteria.where("price").gte(it))
        }
        condition.keyword?.let {
            query.addCriteria(
                Criteria.where("name").regex(it, "i")
            )
        }

        query.with(Sort.by(Sort.Direction.DESC, "createdAt"))
        query.skip(condition.offset)
        query.limit(condition.pageSize)

        return mongoTemplate.find(query, Product::class.java)
    }

    // Aggregation Pipeline
    fun getCategoryStats(): List<CategoryStatsDto> {
        val aggregation = Aggregation.newAggregation(
            Aggregation.match(Criteria.where("status").`is`("ACTIVE")),
            Aggregation.group("categoryId")
                .count().`as`("productCount")
                .avg("price").`as`("avgPrice")
                .sum("reviewSummary.totalCount").`as`("totalReviews"),
            Aggregation.sort(Sort.Direction.DESC, "productCount"),
            Aggregation.limit(10)
        )

        return mongoTemplate
            .aggregate(aggregation, "products", CategoryStatsDto::class.java)
            .mappedResults
    }
}
```

### Change Streams (실시간 데이터 변경 감지)

```kotlin
@Component
class ProductChangeStreamListener(
    private val mongoTemplate: MongoTemplate,
    private val cacheService: CacheService,    // → 2.1 캐싱 전략과 연결
    private val sseEmitters: SseEmitterManager  // → Phase 3 SSE와 연결
) {
    @PostConstruct
    fun startListening() {
        Thread {
            val cursor = mongoTemplate.getCollection("products")
                .watch(listOf(
                    Aggregates.match(
                        Filters.`in`(
                            "operationType",
                            listOf("insert", "update", "replace")
                        )
                    )
                ))
                .fullDocument(FullDocument.UPDATE_LOOKUP)

            cursor.forEach { event ->
                val product = event.fullDocument
                val operationType = event.operationType?.value

                when (operationType) {
                    "insert" -> {
                        // 새 상품 알림
                        sseEmitters.broadcast("new_product", product)
                    }
                    "update", "replace" -> {
                        // 캐시 무효화
                        product?.let {
                            cacheService.evictProduct(it.getObjectId("_id").toHexString())
                        }
                        // 가격 변경 알림
                        sseEmitters.broadcast("product_updated", product)
                    }
                }
            }
        }.apply {
            isDaemon = true
            name = "product-change-stream"
            start()
        }
    }
}
```

> [!warning] Change Streams 요구 사항
> - **Replica Set 필수**: standalone 모드에서는 Change Streams 사용 불가
> - 운영 환경에서는 `resumeToken`을 저장하여 재시작 시 이벤트 유실 방지
> - 높은 쓰기 처리량에서는 oplog 크기 설정 주의

### 트랜잭션 (MongoDB 4.0+)

```kotlin
@Service
class OrderMongoService(
    private val mongoTemplate: MongoTemplate,
    private val transactionManager: MongoTransactionManager
) {
    @Transactional  // Spring @Transactional 사용 가능
    fun createOrder(request: CreateOrderRequest) {
        // 1. 재고 차감
        request.items.forEach { item ->
            val result = mongoTemplate.updateFirst(
                Query(Criteria.where("_id").`is`(item.productId)
                    .and("stockCount").gte(item.quantity)),
                Update().inc("stockCount", -item.quantity),
                Product::class.java
            )
            if (result.modifiedCount == 0L) {
                throw InsufficientStockException(item.productId)
            }
        }

        // 2. 주문 생성
        mongoTemplate.insert(Order.create(request))

        // Replica Set이 없으면 트랜잭션 미지원 → 보상 트랜잭션 패턴 고려
    }
}
```

